// KeyGeneratorStub is a recording test double of KeyGenerator. Each field
// On<Method> configures its method. An unconfigured method records the
// call and returns the zero values of its results.
type KeyGeneratorStub struct {
	OnGenerateKey *KeyGeneratorGenerateKeyStub
	// OnKeyID configures KeyID, which Keeper declares.
	OnKeyID *KeyGeneratorKeyIDStub
	// OnWrap configures Wrap, which Keeper declares.
	OnWrap *KeyGeneratorWrapStub
	// OnUnwrap configures Unwrap, which Keeper declares.
	OnUnwrap *KeyGeneratorUnwrapStub

	// group contains the stub of each method.
	group  *stub.Group
	strict bool
}

// The compiler checks that KeyGeneratorStub implements KeyGenerator.
var _ crypto.KeyGenerator = (*KeyGeneratorStub)(nil)

// NewKeyGeneratorStub returns a double of KeyGenerator that reports its
// failures to tb and applies opts. The double checks the expected counts
// of calls at the end of the test. With a nil tb, the double reports
// nothing.
func NewKeyGeneratorStub(tb assert.TB, opts ...KeyGeneratorStubOption) *KeyGeneratorStub {
	s := &KeyGeneratorStub{
		OnGenerateKey: &KeyGeneratorGenerateKeyStub{
			MethodStub: stub.NewMethodStub[KeyGeneratorGenerateKeyCall](tb, "KeyGenerator.GenerateKey"),
		},
		OnKeyID: &KeyGeneratorKeyIDStub{
			MethodStub: stub.NewMethodStub[KeyGeneratorKeyIDCall](tb, "KeyGenerator.KeyID"),
		},
		OnWrap: &KeyGeneratorWrapStub{
			MethodStub: stub.NewMethodStub[KeyGeneratorWrapCall](tb, "KeyGenerator.Wrap"),
		},
		OnUnwrap: &KeyGeneratorUnwrapStub{
			MethodStub: stub.NewMethodStub[KeyGeneratorUnwrapCall](tb, "KeyGenerator.Unwrap"),
		},
	}
	s.group = stub.NewGroup(
		s.OnGenerateKey.MethodStub,
		s.OnKeyID.MethodStub,
		s.OnWrap.MethodStub,
		s.OnUnwrap.MethodStub,
	)
	for _, opt := range opts {
		opt(s)
	}
	if s.strict {
		s.group.StrictAll()
	}
	s.group.Bind(tb)
	return s
}

